      const paths=isBarMetric?'':specs.map(spec=>{let segments=[],segment=[];buckets.forEach((bucket,index)=>{const value=bucket[spec.key];if(value==null||!Number.isFinite(Number(value))){if(segment.length)segments.push(segment);segment=[];return}segment.push(`${xAt(index).toFixed(1)},${yAt(Number(value),spec).toFixed(1)}`)});if(segment.length)segments.push(segment);return segments.map(points=>`<polyline points="${points.join(' ')}" fill="none" stroke="${spec.color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}).join('');
